import java.time.Instant;
import java.util.*;

enum ChannelType { EMAIL, SMS, PUSH }
enum DeliveryStatus { SUCCESS, FAILED_RETRYABLE, FAILED_PERMANENT }

record Notification(
    String notificationId,
    String userId,
    String templateId,
    Map<String, String> variables,
    Set<ChannelType> channels,
    boolean urgent,
    Instant createdAt
) {
    public static Notification of(String userId, String templateId,
                                   Map<String, String> vars,
                                   Set<ChannelType> channels) {
        return new Notification(UUID.randomUUID().toString(),
            userId, templateId, vars, channels, false, Instant.now());
    }

    public Notification asUrgent() {
        return new Notification(notificationId, userId, templateId,
            variables, channels, true, createdAt);
    }
}

record DeliveryResult(DeliveryStatus status, String errorMessage) {
    public static DeliveryResult success() {
        return new DeliveryResult(DeliveryStatus.SUCCESS, null);
    }
    public static DeliveryResult retryable(String error) {
        return new DeliveryResult(DeliveryStatus.FAILED_RETRYABLE, error);
    }
    public static DeliveryResult permanent(String error) {
        return new DeliveryResult(DeliveryStatus.FAILED_PERMANENT, error);
    }
}

record User(String userId, String email, String phone, String deviceToken) {}

record UserPreferences(
    String userId,
    Map<ChannelType, Boolean> channelEnabled,
    Optional<QuietHours> quietHours
) {
    public boolean isChannelEnabled(ChannelType c) {
        return channelEnabled.getOrDefault(c, true);
    }
}

record QuietHours(int startHour, int endHour) {
    public boolean isInQuietHours(Instant now) {
        int hour = now.atZone(java.time.ZoneId.systemDefault()).getHour();
        if (startHour <= endHour)
            return hour >= startHour && hour < endHour;
        // Overnight (e.g., 22 → 7)
        return hour >= startHour || hour < endHour;
    }
}

record Template(String templateId, ChannelType channel, String subject, String body) {
    public String render(Map<String, String> variables) {
        String result = body;
        for (Map.Entry<String, String> e : variables.entrySet()) {
            result = result.replace("{" + e.getKey() + "}", e.getValue());
        }
        return result;
    }
}

interface NotificationChannel {
    DeliveryResult send(User user, String renderedMessage, String subject);
    ChannelType getChannelType();
}

