// Decorator: adds rate limiting to any channel without changing it
class RateLimitDecorator implements NotificationChannel {
    private final NotificationChannel wrapped;
    private final RateLimiter limiter; // from Problem 6

    public RateLimitDecorator(NotificationChannel wrapped, RateLimiter limiter) {
        this.wrapped = wrapped;
        this.limiter = limiter;
    }

    @Override
    public DeliveryResult send(User user, String body, String subject) {
        String key = wrapped.getChannelType() + ":" + user.userId();
        if (!limiter.allowRequest(key)) {
            return DeliveryResult.retryable("Rate limit exceeded — will retry");
        }
        return wrapped.send(user, body, subject);
    }

    @Override
    public ChannelType getChannelType() { return wrapped.getChannelType(); }
}

class LoggingDecorator implements NotificationChannel {
    private final NotificationChannel wrapped;

    public LoggingDecorator(NotificationChannel wrapped) {
        this.wrapped = wrapped;
    }

    @Override
    public DeliveryResult send(User user, String body, String subject) {
        long start = System.currentTimeMillis();
        DeliveryResult result = wrapped.send(user, body, subject);
        long elapsed = System.currentTimeMillis() - start;
        // log: channel=X user=Y status=Z latency=elapsed
        return result;
    }

    @Override
    public ChannelType getChannelType() { return wrapped.getChannelType(); }
}

import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

record DeliveryTask(
    Notification notification,
    ChannelType channel,
    int attemptNumber,
    long earliestRetryAt
) {}

record DeliveryEvent(String notificationId, String userId,
                     ChannelType channel, DeliveryStatus status, String error) {}

interface DeliveryEventListener {
    void onDelivered(DeliveryEvent event);
    void onFailed(DeliveryEvent event);
}

class NotificationService {
    private static final int MAX_RETRIES = 3;

    private final Map<ChannelType, NotificationChannel> channels;
    private final UserRepository userRepo;
    private final TemplateRepository templateRepo;
    private final BlockingQueue<DeliveryTask> queue = new LinkedBlockingQueue<>();
    private final CopyOnWriteArrayList<DeliveryEventListener> listeners = new CopyOnWriteArrayList<>();
    private final List<DeliveryTask> deadLetter = Collections.synchronizedList(new ArrayList<>());
    private final ExecutorService workers;
    private volatile boolean running = true;

    public NotificationService(Map<ChannelType, NotificationChannel> channels,
                               UserRepository userRepo,
                               TemplateRepository templateRepo,
                               int workerCount) {
        this.channels = channels;
        this.userRepo = userRepo;
        this.templateRepo = templateRepo;
        this.workers = Executors.newFixedThreadPool(workerCount);
        for (int i = 0; i < workerCount; i++) workers.submit(this::workerLoop);
    }

    // ── Public API ──────────────────────
    public void notify(Notification notification) {
        UserPreferences prefs = userRepo.getPreferences(notification.userId());

        for (ChannelType ch : notification.channels()) {
            // Respect user opt-out (urgent overrides this)
            if (!notification.urgent() && !prefs.isChannelEnabled(ch))
                continue;

            // Respect quiet hours (urgent overrides)
            if (!notification.urgent() && prefs.quietHours().isPresent()
                    && prefs.quietHours().get().isInQuietHours(Instant.now()))
                continue;

            queue.offer(new DeliveryTask(notification, ch, 1, 0));
        }
    }

    public void addListener(DeliveryEventListener listener) {
        listeners.add(listener);
    }

    public void shutdown() {
        running = false;
        workers.shutdown();
    }

    // ── Worker loop ─────────────────────
    private void workerLoop() {
        while (running) {
            try {
                DeliveryTask task = queue.poll(1, TimeUnit.SECONDS);
                if (task == null) continue;

                // Honor backoff
                long now = System.currentTimeMillis();
                if (task.earliestRetryAt() > now) {
                    Thread.sleep(task.earliestRetryAt() - now);
                }

                process(task);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    // ── Process a single delivery task ──
    private void process(DeliveryTask task) {
        Notification n = task.notification();
        User user = userRepo.getUser(n.userId());
        if (user == null) {
            emitFailed(n, task.channel(), "Unknown user");
            return;
        }

        Template template = templateRepo.get(n.templateId(), task.channel());
        if (template == null) {
            emitFailed(n, task.channel(), "Unknown template");
            return;
        }

        String body = template.render(n.variables());
        NotificationChannel channel = channels.get(task.channel());
        if (channel == null) {
            emitFailed(n, task.channel(), "Unknown channel");
            return;
        }

        DeliveryResult result = channel.send(user, body, template.subject());

        switch (result.status()) {
            case SUCCESS -> emitDelivered(n, task.channel());
            case FAILED_PERMANENT -> emitFailed(n, task.channel(), result.errorMessage());
            case FAILED_RETRYABLE -> {
                if (task.attemptNumber() >= MAX_RETRIES) {
                    deadLetter.add(task);
                    emitFailed(n, task.channel(),
                        "Max retries exceeded: " + result.errorMessage());
                } else {
                    // Exponential backoff: 1s, 2s, 4s
                    long backoffMs = 1000L * (1L << task.attemptNumber());
                    queue.offer(new DeliveryTask(
                        n, task.channel(), task.attemptNumber() + 1,
                        System.currentTimeMillis() + backoffMs));
                }
            }
        }
    }

    private void emitDelivered(Notification n, ChannelType channel) {
        DeliveryEvent event = new DeliveryEvent(
            n.notificationId(), n.userId(), channel,
            DeliveryStatus.SUCCESS, null);
        for (DeliveryEventListener l : listeners) {
            try { l.onDelivered(event); } catch (Exception ignored) {}
        }
    }

    private void emitFailed(Notification n, ChannelType channel, String error) {
        DeliveryEvent event = new DeliveryEvent(
            n.notificationId(), n.userId(), channel,
            DeliveryStatus.FAILED_PERMANENT, error);
        for (DeliveryEventListener l : listeners) {
            try { l.onFailed(event); } catch (Exception ignored) {}
        }
    }
}

interface UserRepository {
    User getUser(String userId);
    UserPreferences getPreferences(String userId);
}

interface TemplateRepository {
    Template get(String templateId, ChannelType channel);
}
